files.content:
* {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

body {
  display: grid;
  grid-auto-rows: min-content;
  align-content: center;
  place-items: center;
  gap: 50px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 14px;
  background-color: #000;
  block-size: 100%;
}

.lights {
  display: flex;
  gap: 20px;
}

.light {
  --color: #fff;

  box-shadow: 0 0 15px 3px currentColor;
  color: var(--color);
  background-color: currentColor;
  animation: change-color 0.5s linear forwards paused;
  cursor: pointer;
  inline-size: 80px;
  block-size: 80px;
}

@keyframes change-color {
  to {
    --color: #fd24af;
  }
}

.light:hover {
  animation-play-state: running;
}
